CREATE TABLE IF NOT EXISTS `__DATABASE__`.ivis_signal_event (`event_id` FixedString(64), `run_id` String, `source_id` String, `producer` String, `adapter` LowCardinality(String), `session` String, `sequence` UInt64, `record_id` String, `kind` LowCardinality(String), `at_ns` UInt64, `clock_basis` LowCardinality(String), `observed_unix_ns` Nullable(UInt64), `comm` String, `filename` String, `exit_code` Nullable(Int32), `exec_old_pid` UInt32, `thread` Bool, `cluster_uid` String, `cluster_name` String, `node_uid` String, `node_name` String, `boot_id` String, `task_id` String, `pid` UInt32, `tgid` UInt32, `task_start_ns` UInt64, `start_basis` LowCardinality(String), `parent_task_id` String, `parent_pid` UInt32, `parent_tgid` UInt32, `parent_task_start_ns` UInt64, `parent_start_basis` LowCardinality(String), `alias_key` String, `binding_status` LowCardinality(String), `quality` Array(LowCardinality(String)), `received_ns` UInt64, `details_json` String DEFAULT '{}', `content_digest` FixedString(64) DEFAULT '', `inserted_at` DateTime64(3, 'UTC') DEFAULT now64(3)) ENGINE = ReplacingMergeTree ORDER BY (run_id, source_id, task_id, at_ns, event_id) SETTINGS index_granularity = 8192;
